"""Hand-audited benchmark procedures. Counts attach to their exact units."""
def populate(c):
    dart(c); traitgym(c); bend(c); bacbench(c); bgc(c); guanine(c)
    from .collections import populate as collections
    from .mrna import populate as mrna
    collections(c); mrna(c)

def dart(c):
    e=c.code('dart-definition','kundajelab/DART-Eval','README.md','# DART','DART separates regulatory recognition, motif sensitivity, cell context, accessibility and variant effects.',basis='documentation')
    c.suite('dart','DART-Eval','Human regulatory sequence evaluations. A task number can include several targets and adaptation protocols.',e,'dart')
    split=c.code('dart-chromosomes','kundajelab/DART-Eval','src/dnalm_bench/task_1_paired_control/supervised/encode_ccre/train_classifiers/nucleotide_transformer.py','chr6','Supervised cCRE training script declares chromosome validation and test partitions.')
    specs=[
      ('ccre','ENCODE cCREs and shuffled controls','Regulatory-element discrimination','Candidate cis-regulatory element versus dinucleotide-shuffled sequence.','binary classification','Reference regulatory annotations with synthetic negatives',('regulatory',),1),
      ('motif','TF motif insertions / footprint-derived motifs','TF-motif sensitivity','Distinguish sequence containing the specified motif from its matched control.','paired sequence discrimination','Motif/footprint-derived controlled perturbations',('tfbs',),2),
      ('celltype','Cell-type-specific accessible sequences','Cell-type-specific regulatory identity','Assess whether representations separate accessible elements by cell type.','classification / representation analysis','Cell-type-specific accessibility measurements',('regulatory',),3),
      ('accessibility','Quantitative accessibility assays','Chromatin accessibility','Predict quantitative cell-type-specific chromatin accessibility.','regression','Experimental accessibility',('regulatory',),4),
      ('caqtl','African-population caQTLs','caQTL discrimination','Separate accessibility-associated variants from controls after the task-specific eligibility filters.','binary classification','Association-derived QTL labels',('regulatory',),5),
      ('dsqtl','Yoruba dsQTLs','dsQTL discrimination','Separate DNase-sensitivity-associated variants from controls after eligibility filtering.','binary classification','Association-derived QTL labels',('regulatory',),5),
    ]
    original=c.ev('evo-dart-use','evo-supp','A.3.17','Evo 2 original paper uses likelihood Task 1, likelihood Task 2, and likelihood/embedding Task 5; not the entire DART suite.')
    for slug,ds,target,desc,typ,labels,regions,num in specs:
        ev=e
        if num==5:
            ev=c.code('dart-'+slug+'-filters','kundajelab/DART-Eval','src/dnalm_bench/task_2_5_single/experiments/task_5_variant_effect_prediction/variant_tasks.py','def ', 'Task 5 applies dataset-specific used/in-peak filters and computes classification and quantitative metrics; input cohort counts are not final scored counts.')
        t='dart-'+slug
        c.task(t,'dart',target,ds,target,desc,typ,labels,ev,applications=('genome-annotation',) if num<4 else ('regulatory-engineering','gene-therapy','variant-interpretation'),capabilities=('variant-effects',) if num==5 else ('functional-prediction',),regions=regions,populations=('human',),status='paper-audited',input='Regulatory sequence; paired alleles for QTL tasks',limitations='Task-specific final counts and every adaptation recipe still require reconciliation; no single split applies to all DART tasks.')
        if num in (1,2,5):
            p=c.protocol(t,t+'-evo-zero','Evo 2 original DART protocol',original,'zero-shot','Sequence likelihood; Task 5 also compares allele embeddings','No task-label fitting. Task 5 layer choices include a random layer and layers selected using BRCA1 performance.','sequence pair / variant',metrics=('auroc','ap') if num==5 else ('accuracy',),embeddings=None,notes='The original paper reports upstream cohorts >2.3M cCRE sequences, ~577k motif sequences, >219k caQTL and ~28k dsQTL sites; these are not asserted as filtered evaluation counts.')
            c.use('evo2',t,original,'evo',protocol=p)
            c.member('evo-original',t,original,'Only this target/protocol is attributed to the original Evo 2 paper.')
        if num in (1,3,4):
            c.protocol(t,t+'-supervised','DART supervised/readout setting',split,'probe / fine-tune variants','Frozen representations or sequence encoder with task head','For the inspected supervised cCRE script: validation chr6/21; test chr5/10/14/18/20/22; remaining chromosomes train. Do not automatically apply this to every zero-shot or cell-type analysis.','chromosome',metrics=('accuracy','auroc','ap') if num!=4 else ('pearson','spearman'),embeddings=None,notes='Adaptation and split variants must be compared within the same recipe.')
    c.finding(None,'Original Evo 2 usage is restricted to DART 1, 2 and 5. Registering DART does not establish that Evo 2 ran tasks 3 or 4.',original,suite='dart')
    for slug,ds in [('caqtl','African-population caQTLs'),('dsqtl','Yoruba dsQTLs')]:
        ev=c.code('dart-'+slug+'-quantitative','kundajelab/DART-Eval','src/dnalm_bench/task_2_5_single/experiments/task_5_variant_effect_prediction/variant_tasks.py','pearsonr','Task 5 implements correlation with quantitative QTL effects, separate from QTL/control discrimination.')
        t='dart-'+slug+'-magnitude'
        c.task(t,'dart',ds+': quantitative effect',ds,'Quantitative allelic accessibility effect','Compare predicted allelic changes with measured/estimated QTL effect magnitudes. This target is separate from associated-versus-control classification.','regression / ranking','QTL effect estimates',ev,applications=('regulatory-engineering','variant-interpretation'),capabilities=('variant-effects',),regions=('regulatory',),populations=('human',),input='Reference/alternate regulatory sequences',limitations='Filtered cohort and sign conventions require assay-specific reconciliation. Original Evo 2 attribution is not inferred from membership in DART Task 5.')
        c.protocol(t,t+'-protocol','DART quantitative variant score',ev,'zero-shot / score comparison','Reference–alternate likelihood change or declared variant score','Task-specific used/in-peak filters; no fitted readout in the inspected scoring procedure.','variant',metrics=('pearson','spearman'),embeddings=None)

def traitgym(c):
    e=c.code('traitgym-definition','songlab-cal/TraitGym','README.md','mendelian_traits_matched_9','Two human regulatory variant collections; matched-9 and full cohorts, per-chromosome weighted AUPRC, zero-shot and fitted feature models.',basis='documentation')
    c.suite('traitgym','TraitGym','Human Mendelian regulatory disease variants and fine-mapped complex-trait variants; multiple controls and feature-model protocols.',e,'traitgym')
    for slug,ds,target,desc in [
        ('mendelian','Mendelian regulatory variants / OMIM literature curation','Regulatory pathogenicity','Match each pathogenic variant with nine common controls on chromosome, molecular consequence and TSS distance.'),
        ('complex','GWAS fine-mapped noncoding variants','Noncoding causal-variant prioritization','High-PIP variants versus matched low-PIP controls; matching includes chromosome, molecular consequence, TSS distance, LD score and minor allele frequency.')]:
        ev=c.code('traitgym-'+slug+'-data','songlab-cal/TraitGym','workflow/rules/data/'+('mendelian_traits.smk' if slug=='mendelian' else 'complex_traits.smk'),'rule ',desc)
        t='traitgym-'+slug
        c.task(t,'traitgym',target,ds,target,desc,'binary classification','Curated disease association' if slug=='mendelian' else 'Statistical fine-mapping proxy',ev,applications=('variant-interpretation','target-discovery'),capabilities=('variant-effects',),regions=('regulatory',),populations=('human',),input='Human reference/alternate variants and model features',limitations='Statistical fine-mapping and curated pathogenicity are distinct label sources. Matched controls are not a random genome-wide background.')
        c.variant(t,t+'-matched9','Nine matched controls per positive',ev,revision='1fde19555fe8c0a55b1382bdf4c6f7082209f566')
        c.variant(t,t+'-full','Full unmatched collection',e)
        c.protocol(t,t+'-zero','TraitGym zero-shot score',e,'zero-shot','Declared variant-effect score; feature-specific sign / magnitude','No fitted head. Evaluate fixed matched or full cohort; report per-chromosome weighted metric.','variant / chromosome',metrics=(('auprc','Chromosome-specific AUPRC weighted by cohort size; global AUPRC also available'),),embeddings=False)
        code=c.code('traitgym-'+slug+'-model','songlab-cal/TraitGym','workflow/rules/model.smk','rule ','Feature-set logistic regression with chromosome-grouped prediction; score and combined-feature variants are separate protocols.')
        c.protocol(t,t+'-probe','TraitGym chromosome-held-out feature model',code,'frozen probe / score combination','Embeddings, evolutionary scores and/or sequence-to-function features','Hold out chromosome for prediction. Exact training/hyperparameter partition follows model workflow.','chromosome',metrics=('auprc',),embeddings=None,fitted='Logistic regression on specified feature set')

def bend(c):
    e=c.code('bend-tasks','machinelearninglifescience/BEND2','docs/tasks.md','# Choose','Eight tasks; seven frozen-embedding readouts and one nucleotide-probability task. Explicit biological holdouts and distinct design endpoints.',basis='documentation')
    c.suite('bend','BEND 2.0','Sequence priors, molecular function, context dependence, interactions and candidate selection. Selection tasks choose from measured candidate libraries.',e,'bend',notes='A design task does not necessarily require generation. Tissue identification tests represented tissues, not unseen tissues.')
    records=[
      ('prior','Human reference prior panel','Masked nucleotide recovery','Hide the central base in fixed-strand 1,200-bp reference windows.','sequence prediction',('genome',),('sequence-modeling',),'zero-shot','Nucleotide probabilities','512 evaluation windows from distinct 1-Mb blocks; separate 1,024-window baseline-fitting panel.','genomic block',512,'evaluation windows','bits',None),
      ('opensplice','OpenSplice v5','Mutation effect on splicing','Predict mutant-minus-reference splicing response; score within genes and macro-average genes.','regression',('splice','exon','intron'),('variant-effects',),'frozen probe','Frozen sequence embeddings','Five folds holding out whole genes.','gene',590104,'interventions','spearman','466 genes; 590,703 distinct 77–245-bp sequences.'),
      ('context','Siraj saturation mutagenesis','Cell-dependent mutation effect','Predict HepG2-minus-K562 difference in mutation response.','regression',('regulatory',),('variant-effects','context-specific'),'frozen probe','Frozen sequence embeddings','Five folds group each full element and related backgrounds.','regulatory element',170292,'paired substitutions','spearman','128 elements; Siraj shared sequence cache has 169,912 distinct 189–200-bp sequences.'),
      ('background','Siraj saturation mutagenesis','Background-dependent mutation effect','Compare the same mutation across parental sequence backgrounds.','regression',('regulatory',),('variant-effects','genetic-interactions'),'frozen probe','Frozen sequence embeddings','Preserve complete element/background groups in five folds.','regulatory element',68026,'paired mutations','spearman','114 elements; shares readouts with cell-context evaluation.'),
      ('repair','Siraj saturation mutagenesis','Single-edit repair selection','Select a mutation toward a requested response; exclude direct reversion. Rank measured residual against the same request’s options.','candidate selection',('regulatory',),('sequence-selection','variant-effects'),'frozen probe + selection','Predicted effects from frozen embeddings','Use held-out elements and a fixed one-edit menu; candidate outcomes are used after selection.','element / requested repair',331,'repair targets','percentile','110 elements. Percentile is neither an effect size nor a success rate.'),
      ('cell-selective','Siraj pooled-count outcomes','Cell-selective edit selection','Select predicted target-cell effect minus absolute off-target effect, allowing no edit. Evaluate measured outcomes in both cell directions.','candidate selection',('regulatory',),('sequence-selection','context-specific'),'frozen probe + selection','Predicted effects from frozen embeddings','Element holdout; selection without candidate measured outcomes.','locus',167958,'eligible substitutions','utility','127 loci; equal locus weighting. Uses pooled counts, distinct from posterior effect targets.'),
      ('atlas','Atlas of AI-designed enhancers','Multi-cell activity profile selection','Select ten sequences for each of 16 active/inactive-cell requests across twelve cells.','candidate selection',('enhancer',),('sequence-selection','context-specific'),'frozen probe + selection','Frozen sequence embeddings','Fit on 5,246 source constructs; 2,411 candidates separated by sequence family. Exclude 27 source constructs whose families touch candidates.','sequence family / candidate library',7657,'distinct sequences','utility','Two normalized experimental replicates; gain over intent-matched random selection. Replicate values are descriptive, not a confidence interval.'),
      ('tissue','GTEx v10 aggregate expression','Tissue-profile identification','Match predicted profiles across genes to one of 51 represented tissues using 131,072-bp TSS-centered inputs.','classification',('gene','promoter'),('functional-prediction','context-specific','long-context'),'frozen probe','Frozen full-context sequence embeddings','12,146 train genes; 1,350 validation; 5,786 held out, four missing predictions excluded →5,782 scored.','gene',5782,'scored test genes','accuracy','Reference-forward orientation. Full context required; no held-out-tissue transfer claim.'),
    ]
    for slug,ds,target,desc,typ,regions,caps,adapt,interface,split,unit,n,countunit,metric,note in records:
        t='bend-'+slug
        c.task(t,'bend',target,ds,target,desc,typ,'Reference sequence' if slug=='prior' else 'Experimental assay / public aggregate expression',e,applications=('model-development',) if slug=='prior' else (('rna-engineering','variant-interpretation') if slug=='opensplice' else ('regulatory-engineering','gene-therapy')),capabilities=caps,regions=regions,populations=('human',),input=interface,limitations='Released protocol documentation/code inspected; full source assay rows have not yet been independently recounted.')
        c.count(t,n,countunit,e)
        c.protocol(t,t+'-protocol',target+' protocol',e,adapt,interface,split,unit,metrics=((metric,'Macro-gene/element as appropriate; selection utilities follow their own units'),),embeddings=slug!='prior',fitted=None if slug=='prior' else 'Task readout on frozen representations',notes=note)
    c.finding(None,'The code pins HF data revision 0c1dda471ad13c6126c2cd00cb3fa34852e70673. The HF repository head inspected separately is newer; download revision and repository head must remain distinct.',c.code('bend-data','machinelearninglifescience/BEND2','docs/data.md','0c1dda471ad13c6126c2cd00cb3fa34852e70673','Pinned release assets differ from current HF head.',basis='documentation'),suite='bend')

def bacbench(c):
    repo='macwiatrak/BacBench'
    e=c.code('bacbench-essential','macwiatrak/BacBench','bacbench/tasks/essential_genes/README.md','#','Gene-level essentiality from genome-level data; DNA/protein embeddings and supervised readouts.',basis='documentation')
    c.suite('bacbench','BacBench','Bacterial gene, operon, interaction, resistance and organism phenotype evaluations. DNA and protein interfaces differ by task.',e,notes='No one split applies to all tasks. Deprecated strain clustering is not treated as an active task.')
    specs=[
      ('essential','essential_genes','DEG-derived BacBench essential genes','Gene essentiality','binary classification','Experimental essentiality',('gene','cds'),'Gene-level readout from genome embeddings'),
      ('operondb','operon','OperonDB known operons','Operonic gene-pair membership','binary classification','Curated operons',('operon','gene'),'Pairwise cosine similarity among known-operon genes versus sampled negatives'),
      ('operon-longread','operon','Long-read RNA-seq operon data','Adjacent-gene operon boundary','binary classification','Transcript-derived boundaries',('operon','gene'),'Adjacent-gene boundaries from long-read transcription evidence'),
      ('ppi','ppi','STRING combined scores','Protein-pair interaction label','binary classification','Integrated STRING association score; not exclusively direct physical assays',('cds',),'Threshold STRING combined score at 0.6; supervised MLP or cosine baseline'),
      ('amr-binary','antibiotic_resistance','NCBI AST susceptibility labels','Antibiotic resistance call','binary classification','Experimental AST phenotype',('genome',),'One MLP per antibiotic on whole-genome pooled embeddings'),
      ('amr-mic','antibiotic_resistance','NCBI AST MIC labels','Minimum inhibitory concentration','regression','Experimental AST phenotype',('genome',),'One regressor per antibiotic on whole-genome pooled embeddings'),
      ('phenotype','phenotypic_traits','Madin / Traitar / Brbic trait collections','Organism phenotype class','classification','Combined phenotype resources',('genome',),'Whole-genome representation; quantitative source traits are treated as categories'),
    ]
    for slug,path,ds,target,typ,labels,regions,desc in specs:
        ev=c.code('bacbench-'+slug+'-definition',repo,'bacbench/tasks/'+path+'/README.md','#',desc,basis='documentation')
        t='bacbench-'+slug
        c.task(t,'bacbench',target,ds,target,desc,typ,labels,ev,applications=('strain-engineering','microbial-genomics'),capabilities=('functional-prediction',),regions=regions,populations=('bacteria',),status='paper-audited',input='Protein embeddings only in the inspected PPI recipe' if slug=='ppi' else 'DNA or protein/genome representations as supported by the task',limitations='Final retained example counts, label-specific prevalence and complete split manifests remain under audit.')
        split={'essential':'Genome-level train/validation/test partition. Exact genus overlap must be checked in the manifest.', 'operondb':'Known operons versus randomly sampled negative gene sets; no fitted head in this recipe.', 'operon-longread':'Adjacent-gene boundary cohort; exact partition pending.', 'ppi':'Train/validation/test values embedded in parquet; supervised validation tuning, cosine baseline on test.', 'phenotype':'Random default; optional genus column if present, otherwise silently falls back to random.'}.get(slug,'Three random seeds; validation metrics by default. Test reporting is an explicit option; exact genome partition pending.')
        c.protocol(t,t+'-protocol','Inspected BacBench recipe',ev,'zero-shot embedding comparison' if slug.startswith('operon') else 'frozen probe','Pooled sequence / genome embeddings',split,'gene pair' if slug.startswith('operon') or slug=='ppi' else 'genome',embeddings=True,fitted=None if slug.startswith('operon') else 'Task-specific MLP / classifier',notes='PPI has separate supervised and cosine protocols; this summary requires further expansion. Metrics not asserted until scorer audit.')
    # LOAM evaluates subsets, not the whole suite.
    e=c.code('loam-essential','Soilytix/gLMBench','docs/task_bacbench_essentiality.md','#','LOAM gLMBench essentiality uses a frozen logistic readout and macro-genome AUROC; best-layer selection uses the test split.',basis='documentation')
    c.suite('loam-evals','LOAM / gLMBench evaluations','Three biological targets: BacBench essentiality, DGEB DNA EC classification and 11 prokaryotic RNAGym assays.',e,'loam',notes='Last-layer and layer-sweep are protocol variants. LOAM does not evaluate every task in the parent suites.')
    c.member('loam-evals','bacbench-essential',e,'Only the DEG-derived essentiality task is included.')
    for layer in ('last','sweep'):
        p=c.protocol('bacbench-essential','loam-essential-'+layer,'LOAM essentiality '+layer,e,'frozen probe','CDS + 128-bp upstream; fixed frozen block-output embeddings','37 train / 9 validation / 9 test genomes; gLMBench does not embed validation. Layer sweep selects on test.','genome',metrics=(('auroc','Mean across scored test genomes'),('ap','Mean average precision across scored test genomes')),embeddings=True,fitted='Standardized logistic regression, C=1',selection='Fixed last block' if layer=='last' else 'Highest test AUROC; retrospective selection, not validation-selected',notes='Long genes are windowed with overlap then window embeddings averaged.')
        for model,paper,prov in [('loam','loam','original-paper'),('evo2','loam','external-evaluation')]:c.use(model,'bacbench-essential',e,paper,prov,protocol=p)
    c.finding('bacbench-essential','LOAM’s layer-sweep chooses the best layer on the test set. Its score is a retrospective maximum and should be kept separate from the fixed-last-layer result.',e,suite='loam-evals')

def bgc(c):
    e=c.code('bgc-card','Nugkta/BGC-Bench','tools/dataset_card.md','#','BGC-Bench defines five targets with task-specific eligibility and random, scaffold, GCF or class holdouts.',basis='documentation')
    c.suite('bgc','BGC-Bench','Biosynthetic-cluster product labels, chemistry, cross-modal retrieval and adenylation-domain substrate specificity.',e,'bgc',notes='Distinct from BGCs-Bench. MIBiG-derived cohorts and filtered counts differ by task.')
    specs=[('coarse','MIBiG coarse biosynthetic classes','Coarse biosynthetic class','multilabel classification','Annotated biosynthetic classes','gene-cluster product class','functional-prediction','auroc'),('fine','MIBiG / NPClassifier fine labels','Fine natural-product class','multilabel classification','Structure-derived NPClassifier labels','48 retained chemical-class labels','functional-prediction','auroc'),('chem','MIBiG first products / RDKit','Product chemical descriptors','regression','Computed descriptors, not experimentally assayed phenotypes','13 product descriptors','functional-prediction','spearman'),('retrieval','MIBiG cluster–molecule pairs','Cluster-to-molecule retrieval','retrieval','Curated BGC–product pairs','Match cluster representation to molecule representation','sequence-retrieval','recall10'),('adomain','MIBiG adenylation-domain instances','A-domain substrate specificity','classification','Mixed experimental and inferred substrate labels','Predict amino-acid substrate class of a domain','functional-prediction','accuracy')]
    for slug,ds,target,typ,labels,desc,cap,metric in specs:
        t='bgc-'+slug
        c.task(t,'bgc',target,ds,target,desc,typ,labels,e,applications=('natural-products','strain-engineering'),capabilities=(cap,),regions=('cds',) if slug=='adomain' else ('bgc',),populations=('bacteria','fungi'),input='BGC/domain DNA or protein representations; molecular embeddings for retrieval',limitations='Bacterial and fungal source coverage is not balanced. Counts depend on target eligibility and holdout; full taxon-by-split audit remains pending.')
        split='Five folds grouped by parent BGC; GCF alternative also released.' if slug=='adomain' else ('Random, Bemis–Murcko first-product scaffold and BiG-SCAPE c=0.7 GCF holdouts; retrieval also has biosynthetic-class holdout.' if slug=='retrieval' else 'Task-specific random/stratified, scaffold and BiG-SCAPE c=0.7 gene-cluster-family holdouts.')
        c.protocol(t,t+'-probe','BGC-Bench frozen readout',e,'frozen probe' if slug!='retrieval' else 'trained cross-modal readout','Frozen BGC/domain representations',split,'BGC / GCF / product scaffold',metrics=((metric,'Class-macro AUROC/Recall@10, or descriptor correlation as specified by task'),),embeddings=True,fitted={'coarse':'One-vs-rest logistic regression','fine':'One-vs-rest logistic regression','chem':'Ridge regression','retrieval':'Linear contrastive projections with frozen molecule embeddings','adomain':'Domain-level classifier'}[slug],notes='Substrate evidence tiers are not interchangeable; preserve experimental versus inference-based labels. Read the scorer for rare/empty-class handling.')
    c.finding('bgc-adomain','A-domain labels combine experimental evidence, structure-derived inference, homology and sequence predictions. Do not describe all substrate labels as experimental.',e,suite='bgc')
    e2=c.ev('bgcs-definition','bgcs-paper','Methods / benchmark construction','BGCs-Bench probes BGC characteristics from long genomic inputs; separate source and protocol from BGC-Bench.')
    c.suite('bgcs','BGCs-Bench','Long-context biosynthetic-cluster probing; separate from the five-task BGC-Bench.',e2,'bgcs',status='registered',notes='Released probing scripts have been located; per-target class definitions, splits and exact counts remain to be reconciled before task registration.')

def guanine(c):
    e=c.code('guanine-definition','ni-lab/guanine','docs/tasks/dnase_propensity.rst','dnase','GUANinE task pages distinguish epigenomic propensities, conservation, synthetic promoters and variant proxies.',basis='documentation')
    c.suite('guanine','GUANinE v1.1','Sequence function and variant tasks. Some currently released documentation is explicitly under development.',e,'guanine')
    records=[('dnase_propensity','DNase accessibility propensity','regression','Experimental tissue-aggregated accessibility',('regulatory',),'human','functional-prediction'),('ccre_propensity','cCRE epigenetic-marker propensity','multitask prediction','Aggregated epigenomic annotations',('regulatory',),'human','functional-prediction'),('cons30','30-mammal conservation','regression','Phylogenetic conservation proxy',('genome',),'human','evolutionary-inference'),('cons100','100-vertebrate conservation','regression','Phylogenetic conservation proxy',('genome',),'human','evolutionary-inference'),('gpra_c','Synthetic-promoter expression, complex medium','ordinal prediction','Experimental reporter bins 0–17',('promoter',),'yeast','functional-prediction'),('gpra_d','Synthetic-promoter expression, defined medium','ordinal prediction','Experimental reporter bins 0–17',('promoter',),'yeast','functional-prediction'),('cadd_snv','Derived versus simulated SNVs','binary classification','Evolutionary/simulation proxy; not measured pathogenicity',('genome',),'human','variant-effects'),('clinvar_snv','Clinical SNV pathogenicity','binary classification','Clinical annotations',('genome',),'human','variant-effects')]
