        c.task(t,'guanine',target,'GUANinE '+slug,target,labels+'. Refer to the pinned task page for construction and context rules.',typ,labels,ev,applications=('regulatory-engineering',) if slug.startswith('gpra') else ('variant-interpretation',) if cap=='variant-effects' else ('genome-annotation','comparative-genomics'),capabilities=(cap,),regions=regions,populations=(pop,),input='80-bp synthetic promoter' if slug.startswith('gpra') else 'Reference-genome interval or alleles',limitations='Exact release split files/counts and all adaptation recipes remain under audit; current docs sometimes link unfinished build details.')
